var predictionCache = newPredictionCache()

func target*(n: Node): Node = n.son(lbTarget)
func value*(n: Node): Node = n.son(lbValue)
func cond*(n: Node): Node = n.son(lbCond)
func then*(n: Node): Node = n.son(lbThen)
func orelse*(n: Node): Node = n.son(lbOrelse)
func body*(n: Node): Node = n.son(lbBody)
func name*(n: Node): Node = n.son(lbName)
func left*(n: Node): Node = n.son(lbLeft)
func right*(n: Node): Node = n.son(lbRight)
func op*(n: Node): Node = n.son(lbOp)

proc ruleFile(p: var Parser, returnState: int): Node
proc ruleStmt(p: var Parser, returnState: int): Node
proc ruleSimpleStmt(p: var Parser, returnState: int): Node
proc ruleSmallStmt(p: var Parser, returnState: int): Node
proc ruleCompoundStmt(p: var Parser, returnState: int): Node
proc ruleIfStmt(p: var Parser, returnState: int): Node
proc ruleWhileStmt(p: var Parser, returnState: int): Node
proc ruleFuncDef(p: var Parser, returnState: int): Node
proc ruleParams(p: var Parser, returnState: int): Node
proc ruleBlock(p: var Parser, returnState: int): Node
proc ruleExpr(p: var Parser, prec: int, returnState: int): Node
proc ruleArgs(p: var Parser, returnState: int): Node

proc ruleFile(p: var Parser, returnState: int): Node =
  ## `file`, line 18
  result = p.newNode(nkFile)
  p.enter(0, returnState, 0)
  try:
    while p.more(result, {tkPass, tkReturn, tkIf, tkWhile, tkDef, tkLParen,
        tkMinus, tkLBracket, tkID, tkINT, tkSTRING}, {tkEOF}):
      result.add(ruleStmt(p, 0))
    p.match(result, tkEOF)
  except SyntaxError:
    p.recover(result)
  p.leave()

proc ruleStmt(p: var Parser, returnState: int): Node =
  ## `stmt`, line 19
  result = p.newNode(nkStmt)
  p.enter(1, returnState, 0)
  try:
    case p.peek
    of tkPass, tkReturn, tkLParen, tkMinus, tkLBracket, tkID, tkINT, tkSTRING:
      result.add(ruleSimpleStmt(p, 7))
    of tkIf, tkWhile, tkDef:
      result.add(ruleCompoundStmt(p, 9))
    else:
      p.fail({tkPass, tkReturn, tkIf, tkWhile, tkDef, tkLParen, tkMinus,
          tkLBracket, tkID, tkINT, tkSTRING})
  except SyntaxError:
    p.recover(result)
  p.leave()

proc ruleSimpleStmt(p: var Parser, returnState: int): Node =
  ## `simpleStmt`, line 20
  result = p.newNode(nkSimpleStmt)
  p.enter(2, returnState, 0)
  try:
    result.add(ruleSmallStmt(p, 12))
    while p.predict(2, atnStates, atnDecisions, atnRules, predictionCache) == 0:
      p.match(result, tkSemi)
      result.add(ruleSmallStmt(p, 12))
    p.expect({tkSemi})
    if p.peek in {tkSemi}:
      p.match(result, tkSemi)
    else:
      p.expect({tkSemi})
    p.match(result, tkNL)
  except SyntaxError:
    p.recover(result)
  p.leave()

proc ruleSmallStmt(p: var Parser, returnState: int): Node =
  ## `smallStmt`, line 21
  p.enter(3, returnState, 0)
  try:
    case p.predict(5, atnStates, atnDecisions, atnRules, predictionCache)
    of 0:
      result = p.newNode(nkPass)
      p.match(result, tkPass)
    of 1:
      result = p.newNode(nkReturn)
      p.match(result, tkReturn)
      if p.peek in {tkLParen, tkMinus, tkLBracket, tkID, tkINT, tkSTRING}:
        result.add(ruleExpr(p, 0, 23))
      else:
        p.expect({tkLParen, tkMinus, tkLBracket, tkID, tkINT, tkSTRING})
    of 2:
      result = p.newNode(nkAssign)
      result.add(ruleExpr(p, 0, 28), lbTarget)
      p.match(result, tkEq)
      result.add(ruleExpr(p, 0, 27), lbValue)
    of 3:
      result = p.newNode(nkExprStmt)
      result.add(ruleExpr(p, 0, 31))
    else:
      p.fail({tkPass, tkReturn, tkLParen, tkMinus, tkLBracket, tkID, tkINT,
          tkSTRING})
  except SyntaxError:
    p.recover(result)
  p.leave()

proc ruleCompoundStmt(p: var Parser, returnState: int): Node =
  ## `compoundStmt`, line 26
  result = p.newNode(nkCompoundStmt)
  p.enter(4, returnState, 0)
  try:
    case p.peek
    of tkIf:
      result.add(ruleIfStmt(p, 35))
    of tkWhile:
      result.add(ruleWhileStmt(p, 37))
    of tkDef:
      result.add(ruleFuncDef(p, 39))
    else:
      p.fail({tkIf, tkWhile, tkDef})
  except SyntaxError:
    p.recover(result)
  p.leave()

proc ruleIfStmt(p: var Parser, returnState: int): Node =
  ## `ifStmt`, line 28
  result = p.newNode(nkIfStmt)
  p.enter(5, returnState, 0)
  try:
    p.match(result, tkIf)
    result.add(ruleExpr(p, 0, 43), lbCond)
    p.match(result, tkColon)
    result.add(ruleBlock(p, 45), lbThen)
    while p.more(result, {tkElif}, {tkEOF, tkPass, tkReturn, tkIf, tkElse,
        tkWhile, tkDef, tkLParen, tkMinus, tkLBracket, tkID, tkINT, tkSTRING,
        tkDEDENT}):
      p.match(result, tkElif)
      result.add(ruleExpr(p, 0, 49))
      p.match(result, tkColon)
      result.add(ruleBlock(p, 45))
    if p.peek in {tkElse}:
      p.match(result, tkElse)
      p.match(result, tkColon)
      result.add(ruleBlock(p, 41), lbOrelse)
    else:
      p.expect({tkElse})
  except SyntaxError:
    p.recover(result)
  p.leave()

proc ruleWhileStmt(p: var Parser, returnState: int): Node =
  ## `whileStmt`, line 31
  result = p.newNode(nkWhileStmt)
  p.enter(6, returnState, 0)
  try:
    p.match(result, tkWhile)
    result.add(ruleExpr(p, 0, 57), lbCond)
    p.match(result, tkColon)
    result.add(ruleBlock(p, 55), lbBody)
  except SyntaxError:
    p.recover(result)
  p.leave()

proc ruleFuncDef(p: var Parser, returnState: int): Node =
  ## `funcDef`, line 32
  result = p.newNode(nkFuncDef)
  p.enter(7, returnState, 0)
  try:
    p.match(result, tkDef)
    p.match(result, tkID, lbName)
    p.match(result, tkLParen)
    if p.peek in {tkID}:
      result.add(ruleParams(p, 64))
    else:
      p.expect({tkID})
    p.match(result, tkRParen)
    p.match(result, tkColon)
    result.add(ruleBlock(p, 60), lbBody)
  except SyntaxError:
    p.recover(result)
  p.leave()

proc ruleParams(p: var Parser, returnState: int): Node =
  ## `params`, line 33
  result = p.newNode(nkParams)
  p.enter(8, returnState, 0)
  try:
    p.match(result, tkID)
    while p.more(result, {tkComma}, {tkRParen}):
      p.match(result, tkComma)
      p.match(result, tkID)
  except SyntaxError:
    p.recover(result)
  p.leave()

proc ruleBlock(p: var Parser, returnState: int): Node =
  ## `block`, line 34
  result = p.newNode(nkBlock)
  p.enter(9, returnState, 0)
  try:
    case p.peek
    of tkPass, tkReturn, tkLParen, tkMinus, tkLBracket, tkID, tkINT, tkSTRING:
      result.add(ruleSimpleStmt(p, 76))
    of tkNL:
      p.match(result, tkNL)
      p.match(result, tkINDENT)
      while true:
        result.add(ruleStmt(p, 83))
        if not p.more(result, {tkPass, tkReturn, tkIf, tkWhile, tkDef, tkLParen,
            tkMinus, tkLBracket, tkID, tkINT, tkSTRING}, {tkDEDENT}): break
      p.match(result, tkDEDENT)
    else:
      p.fail({tkPass, tkReturn, tkLParen, tkMinus, tkLBracket, tkID, tkINT,
          tkSTRING, tkNL})
  except SyntaxError:
    p.recover(result)
  p.leave()

proc ruleExpr(p: var Parser, prec: int, returnState: int): Node =
  ## `expr`, line 38
  p.enter(10, returnState, prec)
  try:
    case p.peek
    of tkMinus:
      result = p.newNode(nkNeg)
      p.match(result, tkMinus)
      result.add(ruleExpr(p, 9, 89))
    of tkID:
      result = p.newNode(nkName)
      p.match(result, tkID)
    of tkINT:
      result = p.newNode(nkInt)
      p.match(result, tkINT)
    of tkSTRING:
      result = p.newNode(nkStr)
      p.match(result, tkSTRING)
    of tkLParen:
      result = p.newNode(nkParen)
      p.match(result, tkLParen)
      result.add(ruleExpr(p, 0, 100))
      p.match(result, tkRParen)
    of tkLBracket:
      result = p.newNode(nkList)
      p.match(result, tkLBracket)
      if p.peek in {tkLParen, tkMinus, tkLBracket, tkID, tkINT, tkSTRING}:
        result.add(ruleExpr(p, 0, 106))
        while p.more(result, {tkComma}, {tkRBracket}):
          p.match(result, tkComma)
          result.add(ruleExpr(p, 0, 106))
      else:
        p.expect({tkLParen, tkMinus, tkLBracket, tkID, tkINT, tkSTRING})
      p.match(result, tkRBracket)
    else:
      p.fail({tkLParen, tkMinus, tkLBracket, tkID, tkINT, tkSTRING})
    while true:
      case p.predict(20, atnStates, atnDecisions, atnRules, predictionCache, prec)
      of 0:
        result = p.wrap(result, nkCall)
        p.match(result, tkLParen)
        if p.peek in {tkLParen, tkMinus, tkLBracket, tkID, tkINT, tkSTRING}:
          result.add(ruleArgs(p, 112))
        else:
          p.expect({tkLParen, tkMinus, tkLBracket, tkID, tkINT, tkSTRING})
        p.match(result, tkRParen)
      of 1:
        result = p.wrap(result, nkPower, lbLeft)
        p.match(result, tkStarStar)
        result.add(ruleExpr(p, 10, 115), lbRight)
      of 3:
        result = p.wrap(result, nkMul, lbLeft)
        p.matchSet(result, {tkStar, tkSlash}, lbOp)
        result.add(ruleExpr(p, 9, 118), lbRight)
      of 4:
        result = p.wrap(result, nkAdd, lbLeft)
        p.matchSet(result, {tkMinus, tkPlus}, lbOp)
        result.add(ruleExpr(p, 8, 125), lbRight)
      of 5:
        result = p.wrap(result, nkCompare, lbLeft)
        p.matchSet(result, {tkLt, tkGt, tkEqEq}, lbOp)
        result.add(ruleExpr(p, 7, 132), lbRight)
      of high(int): break
      else:
        p.fail({tkLParen, tkStarStar, tkMinus, tkStar, tkSlash, tkPlus, tkLt,
            tkGt, tkEqEq})
  except SyntaxError:
    p.recover(result)
  p.leave()

proc ruleArgs(p: var Parser, returnState: int): Node =
  ## `args`, line 50
  result = p.newNode(nkArgs)
  p.enter(11, returnState, 0)
  try:
    result.add(ruleExpr(p, 0, 142))
    while p.more(result, {tkComma}, {tkRParen}):
      p.match(result, tkComma)
      result.add(ruleExpr(p, 0, 142))
  except SyntaxError:
    p.recover(result)
  p.leave()

const followSets: array[12, set[TokenKind]] = [
  {tkEOF}, # file
  {tkEOF, tkPass, tkReturn, tkIf, tkWhile, tkDef, tkLParen, tkMinus, tkLBracket,
      tkID, tkINT, tkSTRING, tkDEDENT}, # stmt
  {tkEOF, tkPass, tkReturn, tkIf, tkElif, tkElse, tkWhile, tkDef, tkLParen,
      tkMinus, tkLBracket, tkID, tkINT, tkSTRING, tkDEDENT}, # simpleStmt
  {tkEOF, tkSemi, tkNL}, # smallStmt
  {tkEOF, tkPass, tkReturn, tkIf, tkWhile, tkDef, tkLParen, tkMinus, tkLBracket,
      tkID, tkINT, tkSTRING, tkDEDENT}, # compoundStmt
  {tkEOF, tkPass, tkReturn, tkIf, tkWhile, tkDef, tkLParen, tkMinus, tkLBracket,
      tkID, tkINT, tkSTRING, tkDEDENT}, # ifStmt
  {tkEOF, tkPass, tkReturn, tkIf, tkWhile, tkDef, tkLParen, tkMinus, tkLBracket,
      tkID, tkINT, tkSTRING, tkDEDENT}, # whileStmt
  {tkEOF, tkPass, tkReturn, tkIf, tkWhile, tkDef, tkLParen, tkMinus, tkLBracket,
      tkID, tkINT, tkSTRING, tkDEDENT}, # funcDef
  {tkEOF, tkRParen}, # params
  {tkEOF, tkPass, tkReturn, tkIf, tkElif, tkElse, tkWhile, tkDef, tkLParen,
      tkMinus, tkLBracket, tkID, tkINT, tkSTRING, tkDEDENT}, # block
  {tkEOF, tkSemi, tkEq, tkColon, tkLParen, tkRParen, tkComma, tkStarStar,
      tkMinus, tkStar, tkSlash, tkPlus, tkLt, tkGt, tkEqEq, tkRBracket,
      tkNL}, # expr
  {tkEOF, tkRParen}] # args

const ruleNames = ["file", "stmt", "simpleStmt", "smallStmt", "compoundStmt",
    "ifStmt", "whileStmt", "funcDef", "params", "block", "expr", "args"]

proc follows(rule, kind: int): bool = TokenKind(kind) in followSets[rule]

func foundKind*(e: SyntaxErrorInfo): TokenKind =
  ## The kind of the token a syntax error found, if `e.hasToken`.
  TokenKind(e.found)

func expectedKinds*(e: SyntaxErrorInfo): seq[TokenKind] =
  ## The kinds of the tokens that could have come where a syntax error is.
  for k in e.expected: result.add TokenKind(k)

proc parseWith(src, filename: string, formatter: SyntaxErrorFormatter,
    rule: proc (p: var Parser): Node {.nimcall.}): ParseResult[Node] =
  result.diagnostics.filename = filename
  let tokens = tokenize(src, result.diagnostics)
  result.tree = runParser[NodeKind, NodeLabel, TokenKind](tokens, src,
    result.diagnostics, @ruleNames, follows, rule)
  result.diagnostics.formatSyntaxErrors(formatter)

proc parseFile*(src: string, filename = "input",
    formatter: SyntaxErrorFormatter = nil): ParseResult[Node] =
  ## Parses `src` with rule `file`. A `formatter` words the
  ## syntax errors instead of the default messages.
  parseWith(src, filename, formatter, proc (p: var Parser): Node =
    ruleFile(p, -1))

proc parseStmt*(src: string, filename = "input",
    formatter: SyntaxErrorFormatter = nil): ParseResult[Node] =
  ## Parses `src` with rule `stmt`. A `formatter` words the
  ## syntax errors instead of the default messages.
  parseWith(src, filename, formatter, proc (p: var Parser): Node =
    ruleStmt(p, -1))

proc parseSimpleStmt*(src: string, filename = "input",
